struct Comb {
    int n;
    vector<ll> f, inv;

    Comb(int _n) {
        n = _n;
        f.resize(n + 1);
        inv.resize(n + 1);
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % MOD;
        inv[n] = modpow(f[n], MOD - 2);
        for (int i = n; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
    }

