        adj[a].push_back(b);
        adj[b].push_back(a);
    }

vector<int> encode() {
        vector<int> deg(n + 1), code;
        priority_queue<int, vector<int>, greater<int>> q;
        for (int u = 1; u <= n; u++) {
            deg[u] = adj[u].size();
            if (deg[u] == 1) q.push(u);
        }
        for (int i = 0; i < n - 2; i++) {
            int u = q.top();
            q.pop();
            for (int v : adj[u]) {
                if (deg[v] == 0) continue;
                code.push_back(v);
                deg[u] = 0;
                if (--deg[v] == 1) q.push(v);
                break;
            }
        }
        return code;
    }

vector<pair<int, int>> decode(const vector<int> &code) {
        vector<int> deg(n + 1, 1);
        vector<pair<int, int>> edges;
        if (n == 1) return edges;
        for (int v : code) deg[v]++;
        priority_queue<int, vector<int>, greater<int>> q;
        for (int u = 1; u <= n; u++) if (deg[u] == 1) q.push(u);
        for (int v : code) {
            int u = q.top();
            q.pop();
            edges.push_back({u, v});
            deg[u]--;
            if (--deg[v] == 1) q.push(v);
        }
        int a = q.top();
        q.pop();
        edges.push_back({a, q.top()});
        return edges;
    }
};

